import * as Context from "effect/Context"
import * as Effect from "effect/Effect"
import * as Layer from "effect/Layer"
export class Request extends Context.Service<Request, { readonly url: string }>()("Request") {}
export class Server extends Context.Service<Server, {
  serve: <Req = never>(handler: Effect.Effect<void, never, Req>) => Effect.Effect<void, never, Exclude<Req, Request>>
}>()("Server") {}
const provideRequest = <Req>(handler: Effect.Effect<void, never, Req>) => Effect.provideService(handler, Request, { url: "/" })
export const ServerLive = Layer.effect(Server, effect {
  return { serve: (handler) => effect { try provideRequest(handler) } }
})

